function isAgentAction(value: unknown): value is AgentAction {
  if (!value || typeof value !== "object" || !("type" in value)) return false;
  const action = value as Record<string, unknown>;
  if (action.type === "setAutomation") return ["radar", "roteiro", "producao", "publicacao"].includes(String(action.key)) && ["Automática", "Manual"].includes(String(action.value));
  if (action.type === "createIdea") return typeof action.title === "string" && ["Longo", "Short", "Live"].includes(String(action.format));
  if (action.type === "selectAdapter") return typeof action.adapterId === "string";
  if (action.type === "connectPlatform") return ["youtube", "tiktok"].includes(String(action.platform));
  if (action.type === "requestConfirmation") return typeof action.subject === "string" && typeof action.description === "string";
  return false;
}

export default function Workspace({ section }: { section: Section }) {
  return <StudioShell section={section}><Page section={section} /></StudioShell>;
}

function Page({ section }: { section: Section }) {
  switch (section) {
    case "home": return <HomePage />;
    case "radar": return <RadarPage />;
    case "pautas": return <IdeasPage />;
    case "roteiros": return <ScriptsPage />;
    case "estudio": return <StudioPage />;
    case "fila": return <QueuePage />;
    case "publicacoes": return <PublicationPage />;
    case "lives": return <LivesPage />;
    case "analytics": return <AnalyticsPage />;
    case "agente": return <AgentPage />;
    case "integracoes": return <IntegrationsPage />;
    case "configuracoes": return <SettingsPage />;
    case "logs": return <LogsPage />;
  }
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col gap-4 sm:mb-8 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-2 text-[10px] font-black uppercase tracking-[.2em] text-[#8d5cff]">{eyebrow}</p><h1 className="text-2xl font-black tracking-tight text-white sm:text-3xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#9ba7bd]">{description}</p></div>{action}</div>;
}

function Card({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-white/[.075] bg-[#111827]/72 p-4 shadow-[0_16px_50px_rgba(0,0,0,.12)] sm:p-5 ${className}`}>{children}</section>; }
function Button({ children, onClick, variant = "primary", disabled = false, className = "", title }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "secondary" | "danger" | "ghost"; disabled?: boolean; className?: string; title?: string }) {
  const styles = { primary: "bg-[#c6ff4d] text-[#111827] hover:bg-[#d7ff7f]", secondary: "border border-white/12 bg-white/[.06] text-[#e7ecf6] hover:bg-white/[.1]", danger: "border border-[#ff7b70]/25 bg-[#ff7b70]/10 text-[#ffaaa3] hover:bg-[#ff7b70]/18", ghost: "text-[#a9b5c9] hover:bg-white/[.06] hover:text-white" };
  return <button type="button" title={title} onClick={onClick} disabled={disabled} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-3.5 text-xs font-black transition disabled:cursor-not-allowed disabled:opacity-45 ${styles[variant]} ${className}`}>{children}</button>;
}
function Status({ stage }: { stage: keyof typeof stageMeta }) { const meta = stageMeta[stage]; return <span className={`stage stage-${meta.tone}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{meta.label}</span>; }
function Dot({ color = "lime" }: { color?: "lime" | "violet" | "amber" | "coral" }) { return <span className={`inline-block h-2 w-2 rounded-full bg-${color}`} />; }
function Empty({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) { return <Card className="grid min-h-52 place-items-center text-center"><div className="max-w-sm"><div className="mx-auto grid h-11 w-11 place-items-center rounded-2xl bg-[#8d5cff]/12 text-[#b9a5ff]"><Sparkles size={20} /></div><h3 className="mt-3 font-bold text-white">{title}</h3><p className="mt-1.5 text-sm leading-6 text-[#95a2b9]">{description}</p>{action && <div className="mt-4">{action}</div>}</div></Card>; }
function formatDate(date: string) { return date; }
/** Selo de dado de demonstração: nada marcado assim é resultado real. */
function ExampleSeal() { return <span className="tag text-[#ffd98b]" title="Dado de demonstração, não é resultado real do canal">EXEMPLO</span>; }
/** Selo de render simulado: não existe arquivo de vídeo real. */
function SimulatedSeal() { return <span className="tag text-[#ffaaa3]" title="Render simulado: nenhum arquivo de vídeo foi produzido">SIMULADO</span>; }

