function Metric({ icon, label, value, note, tone }: { icon: React.ReactNode; label: string; value: string; note: string; tone: string }) { return <Card className="relative overflow-hidden"><div className={`metric-glow metric-${tone}`} /><div className="relative flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.14em] text-[#8895ac]">{label}</p><p className="mt-3 text-3xl font-black tracking-tight text-white">{value}</p></div><span className={`grid h-9 w-9 place-items-center rounded-xl icon-${tone}`}>{icon}</span></div><p className="relative mt-3 text-xs text-[#93a0b7]">{note}</p></Card>; }
function Progress({ label, value, meta, tone }: { label: string; value: number; meta: string; tone: string }) { return <div><div className="flex justify-between gap-3 text-xs"><span className="font-bold text-[#d8dfed]">{label}</span><span className="text-[#8996ad]">{meta}</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className={`h-full rounded-full progress-${tone}`} style={{ width: `${Math.max(value, 2)}%` }} /></div></div>; }
function QueueItem({ title, description, stage, href }: { title: string; description: string; stage: keyof typeof stageMeta; href: string }) { return <Link href={href} className="flex gap-3 rounded-xl border border-white/[.06] bg-white/[.025] p-3 transition hover:border-white/15 hover:bg-white/[.045]"><div className="mt-0.5"><Status stage={stage} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-white">{title}</p><p className="mt-1 text-xs text-[#8f9bb1]">{description}</p></div><ChevronRight className="shrink-0 self-center text-[#728099]" size={17} /></Link>; }

function RadarPage() {
  const { trends, createIdea } = useStudio();
  const [source, setSource] = useState("Todas");
  const visible = source === "Todas" ? trends : trends.filter(trend => trend.source === source);
  return <><PageHeader eyebrow="PESQUISA DIÁRIA" title="Radar de tendências" description="Nexo cruza volume, crescimento, aderência e lacuna em PT-BR. A pontuação não decide por você — ela explica onde investigar." action={<Button variant="secondary" onClick={() => toast.message("Radar ainda usa dados de exemplo", { description: "A coleta real de Hacker News, GitHub e dev.to entra na Etapa B." })}><RefreshCw size={15} /> Atualizar</Button>} />
    <div className="mb-5 flex gap-2 overflow-x-auto pb-1">{["Todas", "Hacker News", "GitHub", "dev.to", "YouTube"].map(item => <button type="button" key={item} onClick={() => setSource(item)} className={`whitespace-nowrap rounded-xl px-3.5 py-2 text-xs font-bold ${source === item ? "bg-[#c6ff4d] text-[#101421]" : "bg-white/[.045] text-[#9da9bf] hover:bg-white/[.08]"}`}>{item}</button>)}</div>
    <div className="grid gap-4 xl:grid-cols-3">{visible.map((trend, index) => <Card key={trend.id} className="flex flex-col"><div className="flex items-start justify-between gap-4"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#8d5cff]/12 text-xs font-black text-[#baa9ff]">0{index + 1}</span><p className="text-xs font-bold text-[#9aa8bf]">{trend.source}</p>{trend.example && <ExampleSeal />}</div><div className="text-right"><p className="text-xl font-black text-[#c6ff4d]">{trend.score}</p><p className="text-[9px] font-bold uppercase tracking-wider text-[#7f8aa0]">score</p></div></div><h2 className="mt-4 text-base font-black leading-6 text-white">{trend.title}</h2><div className="mt-4 space-y-2 rounded-xl bg-black/20 p-3 text-xs"><Reason icon={<Flame size={13} />} label="Crescimento" value={trend.growth} /><Reason icon={<Gauge size={13} />} label="Aderência" value={trend.fit} /><Reason icon={<Lightbulb size={13} />} label="Lacuna" value={trend.gap} /></div><div className="mt-4 flex flex-wrap gap-1.5">{trend.tags.map(tag => <span key={tag} className="rounded-md bg-white/[.055] px-2 py-1 text-[10px] font-semibold text-[#aab6c9]">{tag}</span>)}</div><div className="mt-auto flex gap-2 pt-5"><Button className="flex-1" onClick={() => createIdea({ title: trend.title, format: "Longo", trendId: trend.id, angle: `Explorar ${trend.gap.toLowerCase()}.` })}><Plus size={14} /> Criar pauta</Button><a href={trend.url} target="_blank" rel="noreferrer" aria-label="Abrir fonte" className="grid h-10 w-10 place-items-center rounded-xl border border-white/12 text-[#9ba8be] hover:bg-white/[.06]"><ExternalLink size={15} /></a></div></Card>)}</div>
  </>;
}
function Reason({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="flex items-center gap-2"><span className="text-[#c6ff4d]">{icon}</span><span className="w-16 text-[#77849b]">{label}</span><span className="font-semibold text-[#c6d0e2]">{value}</span></div>; }

function IdeasPage() {
  const { ideas, createIdea, generateScript } = useStudio();
  const generate = trpc.llm.complete.useMutation();
  const [open, setOpen] = useState(false); const [title, setTitle] = useState(""); const [format, setFormat] = useState<Format>("Longo");
  return <><PageHeader eyebrow="BANCO EDITORIAL" title="Pautas com intenção" description="Pautas vindas do Radar ou dos seus projetos. O próximo passo sempre deixa claro a fase e a decisão necessária." action={<Button onClick={() => setOpen(true)}><Plus size={15} /> Nova pauta</Button>} />
    {open && <FormModal title="Nova pauta" onClose={() => setOpen(false)}><label className="field-label">Tema ou projeto</label><input autoFocus value={title} onChange={event => setTitle(event.target.value)} placeholder="Ex.: Como depurei um agente com ferramentas" className="input" /><label className="mt-4 block field-label">Formato</label><div className="mt-2 flex gap-2">{(["Longo", "Short", "Live"] as Format[]).map(item => <button key={item} type="button" onClick={() => setFormat(item)} className={`rounded-xl px-3 py-2 text-xs font-bold ${format === item ? "bg-[#c6ff4d] text-[#101421]" : "bg-white/7 text-[#aab6c9]"}`}>{item}</button>)}</div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={() => { if (!title.trim()) return toast.error("Dê um nome à pauta"); createIdea({ title, format, origin: "Projeto" }); setOpen(false); setTitle(""); }}>Criar pauta</Button></div></FormModal>}
    <div className="grid gap-3 xl:grid-cols-2">{ideas.map(idea => <Card key={idea.id} className="group"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap gap-2"><span className="tag">{idea.origin}</span><span className="tag">{idea.format}</span>{idea.example && <ExampleSeal />}</div><h2 className="mt-3 text-base font-black text-white">{idea.title}</h2><p className="mt-2 text-sm leading-5 text-[#95a2b9]">{idea.angle}</p></div><Status stage={idea.status} /></div><div className="mt-5 flex items-center justify-between border-t border-white/[.06] pt-3"><span className="text-xs text-[#7e8aa1]">{idea.keywords.join(" · ")}</span>{["pesquisa", "roteiro", "ajuste_pedido"].includes(idea.status) ? <Button variant="secondary" onClick={() => { generate.mutate({ task: "roteiro", messages: [{ role: "system", content: "Você é roteirista técnico do Estúdio de Canal IA. Responda em PT-BR com gancho honesto, problema, demonstração executável, resultado e CTA específico. Não invente resultados." }, { role: "user", content: `Crie um roteiro para a pauta: ${idea.title}. Ângulo: ${idea.angle}. Formato: ${idea.format}.` }] }, { onSuccess: result => { generateScript(idea.id, result.text); toast.success(`Roteiro gerado por ${result.provider === "gemini" ? "Gemini" : "Groq"}`, { description: result.switched ? `Fallback acionado: ${result.fallbackReason}` : "Provedor prioritário respondeu." }); }, onError: error => toast.error("Não foi possível gerar o roteiro", { description: `${error.message} Tente de novo.` }) }); }} disabled={generate.isPending}><WandSparkles size={14} /> {generate.isPending ? "Gerando…" : "Gerar roteiro"}</Button> : <Link href={idea.status === "aguarda_aprov_roteiro" ? "/roteiros" : "/estudio"} className="inline-flex items-center gap-1 text-xs font-bold text-[#c6ff4d]">Abrir <ChevronRight size={14} /></Link>}</div></Card>)}</div>
  </>;
}

function ScriptsPage() {
  const { scripts, ideas, updateScript, approveScript, requestScriptChanges } = useStudio();
  const [selectedId, setSelectedId] = useState(scripts[0]?.id ?? "");
  const selected = scripts.find(script => script.id === selectedId) ?? scripts[0];
  const idea = ideas.find(item => item.id === selected?.ideaId);
  const [draft, setDraft] = useState(selected?.content ?? "");
  useEffect(() => { setDraft(selected?.content ?? ""); }, [selected?.id]);
  if (!selected || !idea) return <Empty title="Nenhum roteiro ainda" description="Crie uma pauta no Radar ou a partir de um projeto para começar." action={<Link href="/pautas"><Button>Ver pautas</Button></Link>} />;
  return <><PageHeader eyebrow="PORTÃO 1" title="Roteiros e versões" description="Aprove somente depois de confirmar que existe demonstração real, originalidade e um ângulo claro para a audiência." />
    <div className="grid gap-5 xl:grid-cols-[280px_1fr]"><Card className="h-fit"><p className="label">ROTEIROS</p><div className="mt-3 space-y-2">{scripts.map(script => <button type="button" key={script.id} onClick={() => setSelectedId(script.id)} className={`w-full rounded-xl border p-3 text-left ${selected.id === script.id ? "border-[#c6ff4d]/35 bg-[#c6ff4d]/[.07]" : "border-white/[.06] bg-white/[.025] hover:bg-white/[.05]"}`}><div className="flex items-start gap-2"><p className="line-clamp-2 flex-1 text-sm font-bold text-white">{script.title}</p>{script.example && <ExampleSeal />}</div><div className="mt-2 flex justify-between"><span className="text-[10px] text-[#8997af]">v{script.version} · {script.updatedAt}</span><span className={`text-[10px] font-bold ${script.status === "Aprovado" ? "text-[#c6ff4d]" : script.status === "Ajuste pedido" ? "text-[#ffaaa3]" : "text-[#ffd98b]"}`}>{script.status}</span></div></button>)}</div></Card><Card><div className="flex flex-col justify-between gap-3 border-b border-white/[.07] pb-4 sm:flex-row"><div><div className="flex flex-wrap gap-2"><Status stage={idea.status} /><span className="tag">{idea.format}</span></div><h2 className="mt-2 text-xl font-black text-white">{selected.title}</h2><p className="mt-1 text-xs text-[#8997ae]">Versão {selected.version} · atualizado {selected.updatedAt}</p></div><div className="flex gap-2"><Button variant="secondary" onClick={() => { navigator.clipboard.writeText(draft); toast.success("Roteiro copiado"); }}><Copy size={14} /> Copiar</Button><Button variant="secondary" onClick={() => { updateScript(selected.id, draft); toast.success("Versão salva e auditada"); }}><Save size={14} /> Salvar</Button></div></div><textarea value={draft} onChange={event => setDraft(event.target.value)} className="script-editor mt-4" aria-label="Editor de roteiro" /><div className="mt-5 flex flex-col gap-3 border-t border-white/[.07] pt-4 sm:flex-row sm:items-center sm:justify-between"><p className="max-w-lg text-xs leading-5 text-[#91a0b7]"><span className="font-bold text-[#c6ff4d]">Checklist:</span> gancho específico, código/tela executado, erro real, resultado e CTA sem promessa vazia.</p><div className="flex gap-2">{selected.status !== "Aprovado" && <Button variant="danger" onClick={() => requestScriptChanges(idea.id)}><Pencil size={14} /> Pedir ajuste</Button>}{selected.status !== "Aprovado" && <Button onClick={() => { updateScript(selected.id, draft); approveScript(idea.id); }}><Check size={15} /> Aprovar roteiro</Button>}</div></div></Card></div>
  </>;
}

function StudioPage() {
  const { ideas, scripts, assets, startRender, addAsset } = useStudio();
  const producible = ideas.filter(idea => ["assets", "ajuste_pedido"].includes(idea.status));
  const [selectedId, setSelectedId] = useState(producible[0]?.id ?? "");
  const selected = producible.find(idea => idea.id === selectedId); const script = scripts.find(item => item.ideaId === selected?.id); const selectedAssets = assets.filter(asset => asset.scriptId === script?.id);
  useEffect(() => { if (!selected && producible[0]) setSelectedId(producible[0].id); }, [selected, producible]);
  return <><PageHeader eyebrow="MONTAGEM" title="Estúdio de produção" description="Organize tela, código, voz, música e legendas antes de renderizar. A prévia só avança após o QA automático." action={<Button variant="secondary" onClick={() => toast.message("Render externo", { description: "No MVP, a fila FFmpeg/GitHub Actions está preparada para conexão." })}><Film size={15} /> Ver jobs</Button>} />
    {!selected ? <Empty title="Nada em produção" description="Aprove um roteiro para liberar assets e render." action={<Link href="/roteiros"><Button>Revisar roteiros</Button></Link>} /> : <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="space-y-4"><Card><p className="label">PAUTA EM PRODUÇÃO</p><select value={selectedId} onChange={event => setSelectedId(event.target.value)} className="input mt-3"><option value={selected.id}>{selected.title}</option>{producible.filter(idea => idea.id !== selected.id).map(idea => <option key={idea.id} value={idea.id}>{idea.title}</option>)}</select><div className="mt-4 flex items-center justify-between"><span className="tag">{selected.format}</span><Status stage={selected.status} /></div><p className="mt-4 text-sm leading-6 text-[#a0acc1]">{selected.angle}</p></Card><Card><div className="flex items-center justify-between"><div><p className="label">ASSETS</p><h2 className="mt-1 font-black text-white">Licenças rastreáveis</h2></div><Button variant="secondary" onClick={() => { if (!script) return; addAsset({ scriptId: script.id, type: "Tela", label: "Captura adicionada agora", license: "Original", status: "Pronto" }); }}><Plus size={14} /> Registrar</Button></div><div className="mt-4 space-y-2">{selectedAssets.length ? selectedAssets.map(asset => <div key={asset.id} className="flex items-center gap-3 rounded-xl bg-white/[.035] p-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#8d5cff]/12 text-[#c3b5ff]"><FileCode2 size={15} /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold text-[#e2e8f5]">{asset.label}</p><p className="mt-0.5 text-[10px] text-[#8b98ae]">{asset.type} · licença: {asset.license}{asset.example && <span className="ml-1.5 font-black text-[#ffd98b]">EXEMPLO</span>}</p></div><span className={`text-[10px] font-black ${asset.status === "Pronto" ? "text-[#c6ff4d]" : "text-[#ffd98b]"}`}>{asset.status}</span></div>) : <p className="text-sm text-[#8d99af]">Registre a primeira captura ou trecho de código.</p>}</div></Card></div><Card><div className="flex items-center justify-between"><div><p className="label">PRÉVIA DE PRODUÇÃO</p><h2 className="mt-1 text-lg font-black text-white">Composição programática</h2></div><span className="tag">Modo gratuito</span></div><div className="video-preview mt-5"><div className="absolute inset-0 bg-[radial-gradient(circle_at_70%_30%,rgba(141,92,255,.3),transparent_32%),linear-gradient(135deg,#101a2d,#070a12)]" /><div className="absolute left-[10%] top-[15%] h-[58%] w-[55%] rounded-lg border border-white/15 bg-[#111a2c] p-3 shadow-2xl"><div className="flex gap-1.5"><span className="h-1.5 w-1.5 rounded-full bg-[#ff7b70]" /><span className="h-1.5 w-1.5 rounded-full bg-[#ffd98b]" /><span className="h-1.5 w-1.5 rounded-full bg-[#c6ff4d]" /></div><p className="mt-6 font-mono text-[9px] text-[#c6ff4d]">const agent = createMCPAgent({'{'}</p><p className="mt-2 font-mono text-[9px] text-[#aeb9d2]"> tools: [reviewPullRequest]</p><p className="font-mono text-[9px] text-[#aeb9d2]">{'})'}</p></div><div className="absolute bottom-[14%] right-[9%] w-[44%] rounded-lg border border-[#c6ff4d]/25 bg-[#101827]/90 p-2.5"><p className="text-[9px] font-bold text-[#c6ff4d]">DEMONSTRAÇÃO REAL</p><p className="mt-1 text-[10px] font-bold text-white">Agente analisando um PR</p></div><div className="absolute bottom-[7%] left-[9%] right-[9%] rounded bg-black/65 p-2 text-center text-[10px] font-semibold text-white">“A ferramenta precisa fazer algo útil — não apenas responder.”</div><button type="button" onClick={() => toast.message("Prévia reproduzida", { description: "O player definitivo será conectado ao arquivo de render." })} className="absolute inset-0 grid place-items-center"><span className="grid h-12 w-12 place-items-center rounded-full bg-[#c6ff4d] text-[#111827] shadow-[0_0_32px_rgba(198,255,77,.4)]"><Play size={19} fill="currentColor" /></span></button></div><div className="mt-5 grid gap-2 sm:grid-cols-3"><MiniStep icon={<AudioLines size={16} />} label="Voz" detail="Piper pt-BR" /><MiniStep icon={<FileCode2 size={16} />} label="Visual" detail="Tela + código" /><MiniStep icon={<MessageSquare size={16} />} label="Legenda" detail="Sincronizada" /></div><div className="mt-5 flex justify-end"><Button onClick={() => startRender(selected.id)}><Rocket size={15} /> Renderizar e rodar QA</Button></div></Card></div>}
  </>;
}
function MiniStep({ icon, label, detail }: { icon: React.ReactNode; label: string; detail: string }) { return <div className="flex items-center gap-3 rounded-xl border border-white/[.06] bg-white/[.025] p-3"><span className="text-[#c6ff4d]">{icon}</span><div><p className="text-xs font-bold text-white">{label}</p><p className="text-[10px] text-[#8490a6]">{detail}</p></div></div>; }

function QueuePage() {
  const { ideas, videos, settings, approveVideo, requestVideoChanges, scheduleVideo, retryVideo } = useStudio();
  const qaReview = trpc.llm.complete.useMutation();
  const scriptQueue = ideas.filter(idea => idea.status === "aguarda_aprov_roteiro"); const videoQueue = videos.filter(video => video.stage === "aguarda_aprov_video"); const scheduled = videos.filter(video => video.stage === "agendado");
  return <><PageHeader eyebrow="DOIS PORTÕES HUMANOS" title="Fila de aprovação" description="A automação organiza e verifica. A decisão editorial e o envio são sempre seus." />
    <div className="grid gap-4 xl:grid-cols-3"><QueueColumn title="Aguardando roteiro" count={scriptQueue.length} tone="amber">{scriptQueue.length ? scriptQueue.map(idea => <div key={idea.id} className="rounded-xl border border-white/[.06] bg-black/15 p-3"><Status stage="aguarda_aprov_roteiro" /><h3 className="mt-3 text-sm font-black text-white">{idea.title}</h3><p className="mt-1 text-xs leading-5 text-[#8f9bb0]">Roteiro disponível no editor, com gancho, demo e CTA.</p><Link href="/roteiros" className="mt-3 inline-flex text-xs font-bold text-[#c6ff4d]">Revisar agora <ChevronRight size={14} /></Link></div>) : <Empty title="Tudo revisado" description="Nenhum roteiro precisa de decisão." />}</QueueColumn>
      <QueueColumn title="Aguardando vídeo" count={videoQueue.length} tone="violet">{videoQueue.length ? videoQueue.map(video => <div key={video.id} className="rounded-xl border border-[#8d5cff]/20 bg-[#8d5cff]/[.035] p-3"><div className="flex flex-wrap items-center gap-2"><Status stage="aguarda_aprov_video" />{video.simulated && <SimulatedSeal />}</div><h3 className="mt-3 text-sm font-black text-white">{video.title}</h3><p className="mt-1 text-xs text-[#9aa7bb]">{video.duration} · {video.qa.some(item => item.verified === false) ? "QA NÃO VERIFICADO (render simulado)" : `QA com ${video.qa.filter(item => item.passed).length}/${video.qa.length} itens validados`}</p><div className="mt-3 space-y-1.5 rounded-lg bg-black/20 p-2.5">{video.qa.map(item => <div key={item.label} className={`flex gap-2 text-[10px] ${item.passed && item.verified !== false ? "text-[#b9c7ad]" : "text-[#ffaaa3]"}`}>{item.passed && item.verified !== false ? <CheckCircle2 size={13} /> : <AlertTriangle size={13} />}<span>{item.label}: {item.note}</span></div>)}</div><div className="mt-3 flex flex-wrap gap-2"><Button variant="secondary" disabled={qaReview.isPending} onClick={() => qaReview.mutate({ task: "qa", messages: [{ role: "system", content: "Você é revisor de QA audiovisual do Estúdio de Canal IA. Responda em PT-BR de forma curta, com riscos e próximos passos. Não invente evidências." }, { role: "user", content: `Revise este checklist: ${video.qa.map(item => `${item.label}: ${item.passed ? "passou" : "falhou"} (${item.note})`).join("; ")}` }] }, { onSuccess: result => toast.success(`QA revisado por ${result.provider === "gemini" ? "Gemini" : "Groq"}`, { description: result.switched ? `Fallback: ${result.fallbackReason}` : result.text.slice(0, 160) }), onError: error => toast.error("QA indisponível", { description: `${error.message} Tente de novo.` }) })}><ShieldCheck size={13} /> {qaReview.isPending ? "Revisando" : "Revalidar QA"}</Button><Button variant="danger" onClick={() => requestVideoChanges(video.id)}><Pencil size={13} /> Ajustar</Button><Button onClick={() => { if (video.simulated && !settings.demoMode) { toast.error("Vídeo simulado", { description: "O Portão 2 está bloqueado para render simulado. Ative o modo demonstração nas Configurações para validar o fluxo, ou produza um vídeo real." }); return; } const hasWarning = video.qa.some(item => !item.passed); if (hasWarning && !confirm(video.simulated ? "Vídeo SIMULADO com QA não verificado. Aprovar em modo demonstração apenas para validar o fluxo?" : "Há itens pendentes no QA. Registrar aprovação com ressalva e liberar para agenda?")) return; approveVideo(video.id, { overrideQa: hasWarning }); }}><Check size={14} /> Aprovar</Button></div></div>) : <Empty title="Fila limpa" description="Nenhum vídeo aguarda sua aprovação." />}</QueueColumn>
      <QueueColumn title="Agenda segura" count={scheduled.length} tone="lime">{scheduled.length ? scheduled.map(video => <div key={video.id} className="rounded-xl border border-[#c6ff4d]/18 bg-[#c6ff4d]/[.035] p-3"><div className="flex flex-wrap items-center gap-2"><Status stage="agendado" />{video.simulated && <SimulatedSeal />}</div><h3 className="mt-3 text-sm font-black text-white">{video.title}</h3><p className="mt-1 text-xs leading-5 text-[#9ba8bc]">{video.scheduledFor ?? "Slot pendente"}<br />Upload em modo manual até o YouTube conectar.</p><Button className="mt-3" variant="secondary" onClick={() => { if (video.simulated && !settings.demoMode) { toast.error("Vídeo simulado", { description: "Ative o modo demonstração nas Configurações para reservar um slot de validação." }); return; } scheduleVideo(video.id); }}><CalendarClock size={14} /> Reservar horário</Button></div>) : <Empty title="Nada agendado" description="Aprove um vídeo para abrir um slot de publicação." />}</QueueColumn></div>
    <div className="mt-5"><Card><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="label">RECUPERAÇÃO</p><p className="mt-1 text-sm font-bold text-white">Falhas nunca ficam escondidas em “carregando”.</p></div><Button variant="secondary" onClick={() => { const item = videos.find(video => video.stage === "erro"); item ? retryVideo(item.id) : toast.message("Nenhum job com erro", { description: "Quando houver um, a nova tentativa aparecerá aqui." }); }}><TimerReset size={14} /> Tentar jobs com erro</Button></div></Card></div>
  </>;
}
function QueueColumn({ title, count, tone, children }: { title: string; count: number; tone: string; children: React.ReactNode }) { return <Card className="min-h-[310px]"><div className="mb-4 flex items-center justify-between"><div><p className="label">{title}</p><h2 className="mt-1 text-lg font-black text-white">{count} {count === 1 ? "item" : "itens"}</h2></div><span className={`grid h-8 w-8 place-items-center rounded-xl icon-${tone}`}>{count}</span></div><div className="space-y-3">{children}</div></Card>; }

function PublicationPage() {
  const { videos, scheduleVideo, publishVideo, settings, connections } = useStudio(); const approved = videos.filter(video => ["agendado", "aprovado_para_agenda"].includes(video.stage)); const youtube = connections.find(item => item.platform === "youtube");
  return <><PageHeader eyebrow="DISTRIBUIÇÃO" title="Publicações e agenda" description="Agende o slot editorial agora. O upload não ocorre até você conectar a plataforma e confirmar a publicação." action={<Link href="/integracoes"><Button variant="secondary"><Link2 size={14} /> Conectar canais</Button></Link>} />
    <div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><Card><p className="label">PRÓXIMOS SLOTS</p><h2 className="mt-1 text-lg font-black text-white">Semana de validação</h2><div className="mt-5 space-y-3">{["Ter · 19:30", "Qui · 19:30", "Sáb · 10:00"].map((slot, index) => <div key={slot} className="flex items-center gap-3"><span className={`grid h-9 w-9 place-items-center rounded-xl text-xs font-black ${index === 0 ? "bg-[#c6ff4d] text-[#101421]" : "bg-white/[.055] text-[#9aa7be]"}`}>{index + 1}</span><div className="flex-1"><p className="text-sm font-bold text-white">{slot}</p><p className="text-xs text-[#8592a8]">{index === 0 ? "Reservado para vídeo aprovado" : "Disponível"}</p></div>{index === 0 && <CheckCircle2 size={17} className="text-[#c6ff4d]" />}</div>)}</div><div className="mt-5 rounded-xl border border-[#ffd98b]/18 bg-[#ffd98b]/[.055] p-3 text-xs leading-5 text-[#ead39e]"><strong>Modo manual ativo:</strong> {youtube?.state}. Vídeos simulados não podem ser autorizados fora do modo demonstração. O sistema gera título, descrição e pacote; você decide o envio final.</div></Card><div className="space-y-3">{approved.length ? approved.map(video => <Card key={video.id}><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="grid h-12 w-16 place-items-center rounded-xl bg-gradient-to-br from-[#8d5cff]/30 to-[#c6ff4d]/15 text-[#c6ff4d]"><Video size={20} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><Status stage={video.stage} /><span className="tag">YouTube + TikTok</span>{video.simulated && <SimulatedSeal />}</div><h2 className="mt-2 truncate text-base font-black text-white">{video.title}</h2><p className="mt-1 text-xs text-[#8e9bb0]">Título, descrição e marcadores de conteúdo sintético serão revisados antes do envio.</p></div><div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={() => downloadBriefing(video.title)}><Download size={14} /> Exportar</Button><Button variant="secondary" onClick={() => publishVideo(video.id)}><ShieldCheck size={14} /> Autorizar publicação</Button><Button onClick={() => { if (video.simulated && !settings.demoMode) { toast.error("Vídeo simulado", { description: "Agendamento bloqueado fora do modo demonstração." }); return; } scheduleVideo(video.id); }}><CalendarClock size={14} /> Agendar</Button></div></div></Card>) : <Empty title="Nenhum vídeo liberado" description="Finalize o Portão 2 para ver opções de agenda e exportação." />}</div></div>
  </>;
}
function downloadBriefing(title: string) { const blob = new Blob([`Estúdio de Canal IA\n\nVídeo: ${title}\n\nStatus: pronto para publicação manual\n\nChecklist: revisar título, descrição, thumbnail, licença de assets e marcação sintética.`], { type: "text/plain" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "pacote-publicacao.txt"; link.click(); URL.revokeObjectURL(url); toast.success("Pacote exportado", { description: "Pronto para a publicação manual." }); }

function LivesPage() {
  const [date, setDate] = useState("");
  return <><PageHeader eyebrow="AO VIVO · FASE 1" title="Lives começam como Estreias" description="Use um vídeo já aprovado como Premiere. RTMP e live 24/7 permanecem preparados, mas exigem infraestrutura e confirmação." />
    <div className="grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><Card className="relative overflow-hidden"><div className="absolute -right-20 -top-20 h-52 w-52 rounded-full bg-[#ff7b70]/15 blur-3xl" /><div className="relative"><span className="tag text-[#ffaaa3]">PREMIERE</span><h2 className="mt-4 text-xl font-black text-white">Agende a primeira Estreia</h2><p className="mt-2 max-w-lg text-sm leading-6 text-[#98a5bb]">A Premiere usa um vídeo final aprovado e mantém o mesmo Portão 2. É a forma mais segura de validar o formato ao vivo antes de RTMP.</p><label className="mt-5 block field-label">Data e horário</label><input type="datetime-local" value={date} onChange={event => setDate(event.target.value)} className="input mt-2" /><Button className="mt-4" onClick={() => date ? toast.success("Estreia rascunhada", { description: "Selecione um vídeo aprovado na agenda para concluir." }) : toast.error("Escolha data e horário") }><CalendarClock size={15} /> Criar rascunho de estreia</Button></div></Card><Card><p className="label">PRÓXIMAS FASES</p><div className="mt-4 space-y-3"><FutureFeature icon={<RadioTower size={17} />} title="RTMP com OBS ou FFmpeg" detail="Bloqueado até teste de sinal, chave RTMP e confirmação de início." /><FutureFeature icon={<Zap size={17} />} title="Canal ao vivo 24/7" detail="Depende de VPS, custo aprovado e monitoramento de saúde." /></div></Card></div>
  </>;
}
function FutureFeature({ icon, title, detail }: { icon: React.ReactNode; title: string; detail: string }) { return <div className="flex gap-3 rounded-xl border border-white/[.06] bg-white/[.025] p-3"><span className="mt-0.5 text-[#8d5cff]">{icon}</span><div><p className="text-sm font-bold text-white">{title}</p><p className="mt-1 text-xs leading-5 text-[#8e9bb0]">{detail}</p></div></div>; }

function AnalyticsPage() {
  return <><PageHeader eyebrow="APRENDIZADO CONTÍNUO" title="Analytics que voltam ao Radar" description="O objetivo não é perseguir números isolados; é aprender quais problemas, demos e formatos seguram a atenção do público certo." action={<Button variant="secondary" onClick={() => toast.message("Sem coleta real ainda", { description: "O YouTube precisa estar autenticado para trazer métricas verdadeiras." })}><RefreshCw size={14} /> Atualizar</Button>} />
    <Card className="mb-5 border-[#ffd98b]/25"><p className="text-xs leading-5 text-[#ead39e]"><strong>Dados de exemplo:</strong> nenhuma métrica real está conectada — o YouTube ainda não está autenticado. Os números abaixo não são resultados do seu canal.</p></Card>
    <div className="grid gap-3 sm:grid-cols-3"><Metric icon={<BarChart3 />} label="Views na semana" value="7.280" note="exemplo · +31% vs. semana anterior" tone="lime" /><Metric icon={<Gauge />} label="CTR médio" value="6,1%" note="Meta de validação: 5%+" tone="violet" /><Metric icon={<Clock3 />} label="Retenção média" value="43%" note="Sinal positivo para longos" tone="amber" /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card><div className="flex items-start justify-between"><div><p className="label">ALCANCE</p><h2 className="mt-1 text-lg font-black text-white">Views por dia</h2></div><span className="tag text-[#ffd98b]">exemplo · últimos 7 dias</span></div><div className="mt-5 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="viewsGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="5%" stopColor="#c6ff4d" stopOpacity={.35}/><stop offset="95%" stopColor="#c6ff4d" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fill: "#76839a", fontSize: 11 }} /><YAxis hide /><Tooltip contentStyle={{ background: "#151c2d", border: "1px solid rgba(255,255,255,.1)", borderRadius: 12, color: "#fff" }} /><Area type="monotone" dataKey="views" stroke="#c6ff4d" fill="url(#viewsGradient)" strokeWidth={2.5} /></AreaChart></ResponsiveContainer></div></Card><Card><p className="label">O QUE FUNCIONOU <ExampleSeal /></p><h2 className="mt-1 text-lg font-black text-white">Insight para o Radar</h2><div className="mt-5 space-y-4"><Insight title="Demos de código mantêm mais atenção" text="Os trechos com terminal e resultado real sustentaram 52% de retenção." /><Insight title="Títulos com problema específico vencem" text="“Como depurei…” gerou 1,8× mais CTR que títulos genéricos." /><Insight title="Próximo experimento" text="Transformar o tutorial MCP em 3 Shorts com falhas e correções reais." /></div><Button className="mt-5 w-full" variant="secondary" onClick={() => toast.message("Insight de exemplo", { description: "A realimentação real do Radar entra depois que as métricas do YouTube estiverem conectadas." })}><Sparkles size={14} /> Realimentar Radar</Button></Card></div>
  </>;
}
function Insight({ title, text }: { title: string; text: string }) { return <div className="border-l-2 border-[#c6ff4d]/60 pl-3"><p className="text-sm font-bold text-white">{title}</p><p className="mt-1 text-xs leading-5 text-[#8e9bb0]">{text}</p></div>; }

function AgentPage() {
  const { chat, addChat, applyAgentActions, adapters } = useStudio(); const [input, setInput] = useState(""); const [loading, setLoading] = useState(false);
  const mutation = trpc.agent.chat.useMutation();
  const confirmMutation = trpc.agent.confirm.useMutation({ onSuccess: result => { addChat({ id: crypto.randomUUID(), sender: "nexo", text: result.message, at: "agora" }); }, onError: error => toast.error("Não foi possível resolver a confirmação", { description: error.message }) });
  const localAnswer = (message: string): { text: string; actions: AgentAction[] } => {
    const lower = message.toLowerCase();
    if ((lower.includes("vídeo") || lower.includes("produção") || lower.includes("render")) && lower.includes("manual")) return { text: "Não foi possível validar essa alteração no servidor.", actions: [] };
    if (lower.includes("publicação automática") || lower.includes("publicar automático")) return { text: "Isso exige sua confirmação explícita porque removeria o Portão 2 e poderia enviar conteúdo para uma plataforma. Mantive a publicação em Manual.", actions: [{ type: "requestConfirmation", subject: "Publicação automática", description: "Ativar publicação automática reduziria a revisão humana obrigatória." }] };
    if (lower.includes("tiktok") && (lower.includes("conect") || lower.includes("ativ"))) return { text: "Preparei a conexão TikTok para receber credenciais OAuth no cofre. Nenhuma conta foi autenticada e nenhum conteúdo será enviado até você concluir essa conexão.", actions: [{ type: "connectPlatform", platform: "tiktok" }] };
    if (lower.includes("pauta") || lower.includes("ideia")) return { text: "A criação de pauta precisa ser validada pelo servidor.", actions: [] };
    if (lower.includes("fallback")) { const fallback = adapters.find(adapter => adapter.fallback); return { text: fallback ? `O fallback configurado para ${fallback.capability} é ${fallback.provider}. Ele entra apenas se o ativo falhar ou atingir o limite. Chaves permanecem inacessíveis para mim.` : "Não há fallback configurado para essa função ainda.", actions: [] }; }
    return { text: "O melhor próximo passo é revisar o roteiro MCP ou aprovar a prévia do Zarith. Ambos já têm contexto e checklist; posso também criar uma pauta nova ou ajustar uma etapa para Manual.", actions: [] };
  };
  const send = () => { const message = input.trim(); if (!message || loading) return; setInput(""); addChat({ id: crypto.randomUUID(), sender: "user", text: message, at: "agora" }); setLoading(true); mutation.mutate({ message }, { onSuccess: result => { const actions = Array.isArray(result.actions) ? result.actions.filter(isAgentAction) : []; addChat({ id: crypto.randomUUID(), sender: "nexo", text: result.message, at: "agora", actions }); if (actions.length) applyAgentActions(actions); setLoading(false); }, onError: error => { addChat({ id: crypto.randomUUID(), sender: "nexo", text: `Não consegui validar a operação no servidor. ${error.message} Tente de novo.`, at: "agora", actions: [] }); setLoading(false); } }); };
  return <><PageHeader eyebrow="AGENTE OPERADOR" title="Nexo, seu produtor executivo" description="Nexo pesquisa, estrutura e opera ferramentas permitidas. Ele não vê segredos, não publica sozinho e pede confirmação para mudanças sensíveis." />
    <div className="grid gap-5 xl:grid-cols-[1fr_.4fr]"><Card className="flex min-h-[560px] flex-col"><div className="flex items-center gap-3 border-b border-white/[.07] pb-4"><span className="nexo-pulse grid h-10 w-10 place-items-center rounded-xl bg-[#8d5cff]/16 text-[#c5b8ff]"><Bot size={20} /></span><div><p className="text-sm font-black text-white">Nexo</p><p className="mt-0.5 text-xs text-[#a7b3c9]"><span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-[#c6ff4d]" />Pronto para operar com limites</p></div></div><div className="flex-1 space-y-4 overflow-y-auto py-5">{chat.map(message => <div key={message.id} className={`flex ${message.sender === "user" ? "justify-end" : "justify-start"}`}><div className={`max-w-[86%] rounded-2xl px-4 py-3 text-sm leading-6 ${message.sender === "user" ? "rounded-br-md bg-[#c6ff4d] text-[#152013]" : "rounded-bl-md border border-white/[.08] bg-white/[.045] text-[#d6ddec]"}`}><p>{message.text}</p>{message.actions?.filter(action => action.type === "requestConfirmation" && action.confirmationId).map(action => action.type === "requestConfirmation" && action.confirmationId ? <div key={action.confirmationId} className="mt-3 flex flex-wrap gap-2 border-t border-white/10 pt-3"><Button disabled={confirmMutation.isPending} onClick={() => confirmMutation.mutate({ confirmationId: action.confirmationId!, approved: true })}><Check size={13} /> Confirmar</Button><Button variant="secondary" disabled={confirmMutation.isPending} onClick={() => confirmMutation.mutate({ confirmationId: action.confirmationId!, approved: false })}><XCircle size={13} /> Cancelar</Button></div> : null)}<span className={`mt-2 block text-[10px] ${message.sender === "user" ? "text-[#34411d]" : "text-[#8090a7]"}`}>{message.at}</span></div></div>)}{loading && <div className="flex gap-2 text-sm text-[#a9b6ca]"><span className="mt-2 h-2 w-2 animate-bounce rounded-full bg-[#8d5cff]" /><span className="mt-2 h-2 w-2 animate-bounce rounded-full bg-[#8d5cff] [animation-delay:120ms]" /><span className="mt-2 h-2 w-2 animate-bounce rounded-full bg-[#8d5cff] [animation-delay:240ms]" /></div>}</div><form onSubmit={event => { event.preventDefault(); send(); }} className="flex gap-2 border-t border-white/[.07] pt-4"><input value={input} onChange={event => setInput(event.target.value)} className="input flex-1" placeholder="Ex.: deixe a geração de vídeo manual" /><Button disabled={!input.trim() || loading}><Send size={15} /> Enviar</Button></form></Card><div className="space-y-4"><Card><p className="label">FERRAMENTAS PERMITIDAS</p><div className="mt-3 space-y-2">{["Consultar fila e status", "Criar ou editar pautas", "Disparar etapas seguras", "Trocar adaptador ativo", "Ajustar automação por etapa"].map(item => <div key={item} className="flex items-center gap-2 text-xs text-[#b7c2d4]"><CheckCircle2 size={14} className="text-[#c6ff4d]" />{item}</div>)}</div></Card><Card><p className="label">LIMITES INEGOCIÁVEIS</p><div className="mt-3 space-y-2">{["Nunca mostra ou lê segredos", "Nunca envia publicação sem aprovação", "Pede confirmação para custos e exclusões", "Registra toda mudança no log"].map(item => <div key={item} className="flex gap-2 text-xs leading-5 text-[#a7b2c6]"><LockKeyhole size={14} className="mt-0.5 shrink-0 text-[#ffcf7a]" />{item}</div>)}</div></Card><Card><p className="label">ATALHOS</p><div className="mt-3 grid gap-2"><Button variant="secondary" onClick={() => setInput("Crie uma pauta sobre depuração de agentes")}>Criar pauta</Button><Button variant="secondary" onClick={() => setInput("Deixe a geração de vídeo manual")}>Produção manual</Button><Button variant="secondary" onClick={() => setInput("Qual é o fallback configurado?")}>Ver fallback</Button></div></Card></div></div>
  </>;
}

function IntegrationsPage() {
  const { connections, requestPlatformConnection, adapters, selectAdapter } = useStudio();
  return <><PageHeader eyebrow="ADAPTADORES TROCVÉIS" title="Integrações e provedores" description="Conecte plataformas apenas no cofre. Troque provedores sem mudar o núcleo do estúdio e mantenha um fallback para cada etapa crítica." />
    <div className="grid gap-4 xl:grid-cols-2">{connections.map(connection => <Card key={connection.platform}><div className="flex items-start justify-between gap-4"><div className="flex gap-3"><span className={`grid h-11 w-11 place-items-center rounded-xl ${connection.platform === "youtube" ? "bg-[#ff5353]/12 text-[#ff7b70]" : "bg-[#23d5b8]/12 text-[#5eefd4]"}`}><Play size={19} fill="currentColor" /></span><div><h2 className="font-black text-white">{connection.label}</h2><p className="mt-1 text-xs font-bold text-[#b1bdcf]">{connection.state}</p></div></div><span className="tag">{connection.enabled ? "Ativa" : "Protegida"}</span></div><p className="mt-4 text-sm leading-6 text-[#95a2b8]">{connection.detail}</p><div className="mt-4 flex gap-2"><Button onClick={() => requestPlatformConnection(connection.platform)}><Link2 size={14} /> Preparar conexão</Button><Button variant="secondary" onClick={() => toast.message("Escopos mínimos", { description: connection.platform === "youtube" ? "youtube.upload e youtube.readonly; revogáveis no painel." : "Escopos serão definidos quando a app TikTok for conectada." })}><Info size={14} /> Escopos</Button></div></Card>)}</div>
    <div className="mt-6"><p className="label">ADAPTADORES DE PRODUÇÃO</p><div className="mt-3 grid gap-3 xl:grid-cols-2">{adapters.map(adapter => <Card key={adapter.id} className="flex items-center gap-3"><span className={`grid h-9 w-9 place-items-center rounded-xl ${adapter.active ? "bg-[#c6ff4d] text-[#101421]" : "bg-white/[.06] text-[#8491a9]"}`}>{adapter.active ? <Check size={17} /> : <Zap size={16} />}</span><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="text-xs font-black text-white">{adapter.capability}</p>{adapter.fallback && <span className="tag text-[#c5b7ff]">fallback</span>}</div><p className="truncate text-xs text-[#929fb6]">{adapter.provider} · {adapter.plan}</p></div><Button variant={adapter.active ? "ghost" : "secondary"} disabled={adapter.active} title={adapter.active ? "Já é o adaptador ativo" : undefined} onClick={() => selectAdapter(adapter.id)}>{adapter.active ? "Ativo" : "Usar"}</Button></Card>)}</div></div>
  </>;
}

function SettingsPage() {
  const studio = useStudio(); const { settings, setAutomation, updateSettings, resetDemo, connections, importDeviceData, setDemoMode, clearExampleData, trends, ideas, scripts, videos } = studio;
  const exampleCount = [...trends, ...ideas, ...scripts, ...videos].filter(item => item.example).length; const [voiceConsent, setVoiceConsent] = useState(false); const [currentPassword, setCurrentPassword] = useState(""); const [newPassword, setNewPassword] = useState("");
  const changePassword = trpc.auth.changePassword.useMutation({ onSuccess: () => { toast.success("Senha alterada"); setCurrentPassword(""); setNewPassword(""); }, onError: error => toast.error("Não foi possível alterar a senha", { description: error.message }) });
  const logoutAll = trpc.auth.logoutAll.useMutation({ onSuccess: () => { toast.success("Todas as sessões foram encerradas"); window.location.assign("/login"); }, onError: error => toast.error("Não foi possível encerrar as sessões", { description: error.message }) });
  const exportData = () => { const file = new Blob([JSON.stringify({ exportedAt: new Date().toISOString(), trends: studio.trends, ideas: studio.ideas, scripts: studio.scripts, assets: studio.assets, videos: studio.videos, renderJobs: studio.renderJobs, adapters: studio.adapters, connections, settings, audit: studio.audit, chat: studio.chat }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(file); const a = document.createElement("a"); a.href = url; a.download = "estudio-canal-ia-dados.json"; a.click(); URL.revokeObjectURL(url); toast.success("Dados exportados", { description: "Pautas, roteiros, assets, jobs e auditoria foram incluídos." }); };
  return <><PageHeader eyebrow="CONTROLE SEM CÓDIGO" title="Configurações poderosas" description="Mude automação, provedores, voz, metas e limites sem tocar na implementação. Mudanças sensíveis continuam pedindo confirmação." />
    <LLMProviderSettings />
    <div className="grid gap-5 xl:grid-cols-[1fr_.78fr]"><div className="space-y-5"><Card><p className="label">ESTADO NO NEON</p><h2 className="mt-1 text-lg font-black text-white">Fonte da verdade do estúdio</h2><p className="mt-2 text-xs leading-5 text-[#95a2b8]">O estado operacional agora é lido e salvo no Neon. Importe uma cópia já existente neste aparelho para iniciar a migração sem perder dados.</p><Button className="mt-4 w-full" variant="secondary" onClick={() => importDeviceData()}><UploadCloud size={14} /> Importar dados deste aparelho</Button></Card><Card className="border-[#ffd98b]/25"><div className="flex items-center justify-between"><div><p className="label text-[#ffd98b]">DADOS DE EXEMPLO E DEMONSTRAÇÃO</p><h2 className="mt-1 text-lg font-black text-white">Separe o que é real do que é amostra</h2></div><Info size={20} className="text-[#ffd98b]" /></div><p className="mt-2 text-xs leading-5 text-[#95a2b8]">{exampleCount} itens marcados como <strong>EXEMPLO</strong> estão no seu estado (pautas, roteiros, sinais do Radar, assets, vídeos e jobs). Nada disso é resultado real do seu canal.</p><div className="mt-4 flex flex-wrap gap-2"><Button variant="secondary" onClick={() => { if (confirm("Remover todos os itens marcados como EXEMPLO? Dados reais não são afetados.")) clearExampleData(); }}><Trash2 size={14} /> Limpar dados de exemplo</Button><Button variant={settings.demoMode ? "danger" : "secondary"} onClick={() => { if (settings.demoMode) { setDemoMode(false); return; } if (confirm("Ativar o modo demonstração permite aprovar vídeos SIMULADOS no Portão 2 e na agenda, somente para validar o fluxo. Nenhum vídeo real é produzido. Continuar?")) setDemoMode(true); }}>{settings.demoMode ? "Desativar modo demonstração" : "Ativar modo demonstração"}</Button></div>{settings.demoMode ? <p className="mt-3 rounded-xl border border-[#ff7b70]/25 bg-[#ff7b70]/[.07] p-3 text-xs leading-5 text-[#ffc4bf]"><strong>Modo demonstração ATIVO:</strong> vídeos simulados podem avançar nos portões. Isso não produz vídeo real — serve apenas para validar o fluxo.</p> : <p className="mt-3 rounded-xl border border-white/[.07] bg-white/[.025] p-3 text-xs leading-5 text-[#8f9cb2]">Com o modo demonstração desligado, vídeos com render simulado não passam pelo Portão 2 nem entram na agenda.</p>}</Card><Card><div className="flex items-center justify-between"><div><p className="label">AUTOMAÇÃO POR ETAPA</p><h2 className="mt-1 text-lg font-black text-white">Você decide onde o piloto automático atua</h2></div><Settings2 size={20} className="text-[#c6ff4d]" /></div><div className="mt-4 space-y-3">{([ ["radar", "Pesquisar tendências"], ["roteiro", "Gerar roteiro"], ["producao", "Gerar vídeo"], ["publicacao", "Publicar"] ] as const).map(([key, label]) => <div key={key} className="flex items-center justify-between gap-4 rounded-xl border border-white/[.06] bg-white/[.025] p-3"><div><p className="text-sm font-bold text-white">{label}</p><p className="mt-1 text-xs text-[#8b98af]">{key === "publicacao" ? "Permanece manual por segurança." : "Altere quando quiser."}</p></div><div className="flex rounded-lg bg-black/20 p-1">{(["Automática", "Manual"] as const).map(value => <button key={value} type="button" onClick={() => { if (key === "publicacao" && value === "Automática") { toast.warning("Use o Nexo para solicitar confirmação; o servidor mantém o Portão 2."); return; } setAutomation(key, value); }} className={`rounded-md px-2.5 py-1.5 text-[10px] font-black ${settings.automation[key] === value ? "bg-[#c6ff4d] text-[#101421]" : "text-[#8996ad]"}`}>{value}</button>)}</div></div>)}</div></Card><Card><p className="label">METAS E CUSTO</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><FieldNumber label="Vídeos longos / semana" value={settings.weeklyGoal.longos} onChange={value => updateSettings({ weeklyGoal: { ...settings.weeklyGoal, longos: value } })} /><FieldNumber label="Shorts / semana" value={settings.weeklyGoal.shorts} onChange={value => updateSettings({ weeklyGoal: { ...settings.weeklyGoal, shorts: value } })} /><FieldNumber label="Lives / semana" value={settings.weeklyGoal.lives} onChange={value => updateSettings({ weeklyGoal: { ...settings.weeklyGoal, lives: value } })} /><FieldNumber label="Teto mensal (R$)" value={settings.monthlyCap} onChange={value => { if (value > settings.monthlyCap && !confirm("Aumentar o teto de gasto requer sua confirmação. Continuar?")) return; updateSettings({ monthlyCap: value }); }} /></div></Card><Card><p className="label">VOZ E CONSENTIMENTO</p><div className="mt-4 flex flex-wrap gap-2">{(["TTS", "Sua voz", "Música + texto"] as const).map(mode => <button type="button" key={mode} onClick={() => { if (mode === "Sua voz" && !voiceConsent) return toast.warning("Registre seu consentimento primeiro"); updateSettings({ voiceMode: mode }); }} className={`rounded-xl border px-3 py-2 text-xs font-bold ${settings.voiceMode === mode ? "border-[#c6ff4d]/45 bg-[#c6ff4d]/10 text-[#eaffc6]" : "border-white/[.08] bg-white/[.025] text-[#98a5ba]"}`}>{mode}</button>)}</div><label className="mt-4 flex cursor-pointer gap-3 rounded-xl border border-[#ffcf7a]/18 bg-[#ffcf7a]/[.04] p-3 text-xs leading-5 text-[#c7b786]"><input type="checkbox" checked={voiceConsent} onChange={event => setVoiceConsent(event.target.checked)} className="mt-1 accent-[#c6ff4d]" />Confirmo que qualquer amostra enviada é da minha própria voz e autorizo seu uso somente neste estúdio.</label></Card></div>
      <div className="space-y-5"><Card><p className="label">SEGURANÇA DA CONTA</p><h2 className="mt-1 text-lg font-black text-white">Trocar senha</h2><p className="mt-2 text-xs leading-5 text-[#95a2b8]">A senha inicial veio do cofre. Depois desta troca, o novo hash fica salvo no Neon e passa a ter precedência.</p><div className="mt-4 space-y-3"><input type="password" autoComplete="current-password" placeholder="Senha atual" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} className="input" /><input type="password" autoComplete="new-password" placeholder="Nova senha (mínimo 12 caracteres)" value={newPassword} onChange={event => setNewPassword(event.target.value)} className="input" /><Button className="w-full" disabled={changePassword.isPending || !currentPassword || newPassword.length < 12} onClick={() => changePassword.mutate({ currentPassword, newPassword })}>{changePassword.isPending ? "Salvando…" : "Alterar senha"}</Button><Button className="mt-2 w-full" variant="secondary" disabled={logoutAll.isPending} onClick={() => logoutAll.mutate()}>{logoutAll.isPending ? "Encerrando…" : "Encerrar todas as sessões"}</Button></div></Card><Card><p className="label">DADOS E SEGREDOS</p><div className="mt-4 space-y-3"><SecurityRow icon={<LockKeyhole size={16} />} title="Cofre de credenciais" text="Chaves ficam somente nas variáveis da Vercel e nunca são exibidas." status="Ativo" /><SecurityRow icon={<ShieldCheck size={16} />} title="Neon Postgres" text="Projeto dedicado conectado por segredo de ambiente (STUDIO_DATABASE_URL)." status="Ativo" /><SecurityRow icon={<UploadCloud size={16} />} title="Exportação" text="Baixe uma cópia das suas configurações a qualquer momento." status="Ativo" /></div><Button className="mt-5 w-full" variant="secondary" onClick={exportData}><Download size={14} /> Exportar meus dados</Button></Card><Card><p className="label">MODO DE AUTONOMIA</p><h2 className="mt-1 text-lg font-black text-white">{settings.autonomy}</h2><p className="mt-2 text-sm leading-6 text-[#93a0b6]">Revisão total é o padrão e mantém os dois portões. Amostra continua bloqueada até uma política explícita ser implementada.</p><Button className="mt-4 w-full" variant="secondary" disabled title="Indisponível: precisa de política de amostragem aprovada">Modo amostra (futuro)</Button></Card><Card className="border-[#ff7b70]/18"><p className="label text-[#ffaaa3]">ZONA DE MANUTENÇÃO</p><p className="mt-2 text-sm leading-6 text-[#9faabd]">Restaurar dados de demonstração é reversível neste dispositivo. Dados de produção serão apagados somente com confirmação e exportação prévia.</p><Button className="mt-4 w-full" variant="danger" onClick={() => { if (confirm("Restaurar o conjunto de demonstração deste navegador? Alterações locais atuais serão substituídas.")) resetDemo(); }}><RefreshCw size={14} /> Restaurar demonstração</Button></Card></div></div>
  </>;
}
function FieldNumber({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) { return <label><span className="field-label">{label}</span><input type="number" min="0" value={value} onChange={event => onChange(Math.max(0, Number(event.target.value)))} className="input mt-2" /></label>; }
function SecurityRow({ icon, title, text, status }: { icon: React.ReactNode; title: string; text: string; status: string }) { return <div className="flex gap-3"><span className="mt-0.5 text-[#c6ff4d]">{icon}</span><div className="flex-1"><div className="flex justify-between gap-2"><p className="text-xs font-bold text-white">{title}</p><span className={`text-[10px] font-black ${status === "Ativo" ? "text-[#c6ff4d]" : "text-[#ffd98b]"}`}>{status}</span></div><p className="mt-1 text-xs leading-5 text-[#8f9cb2]">{text}</p></div></div>; }

function LogsPage() {
  const { audit } = useStudio();
  return <><PageHeader eyebrow="OBSERVABILIDADE" title="Logs e custos" description="Toda decisão de Nexo e toda transição de etapa ficam rastreáveis. Nunca são gravados tokens, chaves ou conteúdo de segredos." />
    <div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><Card><p className="label">CUSTO POR VÍDEO</p><div className="mt-5 text-center"><p className="text-4xl font-black text-[#c6ff4d]">R$ 0,00</p><p className="mt-2 text-xs text-[#8e9bb2]">Validação com adaptadores gratuitos</p></div><div className="mt-5 space-y-3 border-t border-white/[.07] pt-4"><CostRow label="Pesquisa" value="R$ 0,00" /><CostRow label="Roteiro" value="R$ 0,00" /><CostRow label="Voz / render" value="R$ 0,00" /><CostRow label="Upload YouTube" value="bloqueado" /></div><Button className="mt-5 w-full" variant="secondary" onClick={() => toast.message("Limites ativos", { description: "Alertas aparecerão antes de qualquer custo novo." })}><Gauge size={14} /> Ver alertas de quota</Button></Card><Card><div className="flex items-center justify-between"><div><p className="label">AUDITORIA</p><h2 className="mt-1 text-lg font-black text-white">Últimas ações</h2></div><ListFilter size={19} className="text-[#8d5cff]" /></div><div className="mt-4 divide-y divide-white/[.06]">{audit.map(entry => <div key={entry.id} className="flex gap-3 py-3 first:pt-0"><span className={`mt-1.5 h-2 w-2 rounded-full ${entry.actor === "Nexo" ? "bg-[#8d5cff]" : entry.actor === "Você" ? "bg-[#c6ff4d]" : "bg-[#ffd98b]"}`} /><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-1"><p className="text-xs font-bold text-[#e0e6f1]"><span className="text-[#a9b5c8]">{entry.actor}</span> · {entry.action}</p><span className="text-[10px] text-[#78859a]">{entry.at}</span></div><p className="mt-1 truncate text-xs text-[#95a1b7]">{entry.example && <span className="mr-1.5 font-black text-[#ffd98b]">EXEMPLO</span>}{entry.target}{entry.detail ? ` — ${entry.detail}` : ""}</p></div></div>)}</div></Card></div>
  </>;
}
function CostRow({ label, value }: { label: string; value: string }) { return <div className="flex justify-between text-xs"><span className="text-[#97a3b8]">{label}</span><span className="font-bold text-[#e1e7f3]">{value}</span></div>; }

function FormModal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-[60] grid place-items-end bg-black/65 p-0 backdrop-blur-sm sm:place-items-center sm:p-5"><div className="w-full max-w-lg rounded-t-[26px] border border-white/[.1] bg-[#151c2d] p-5 shadow-2xl sm:rounded-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-black text-white">{title}</h2><button type="button" aria-label="Fechar" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/[.06] text-[#a3afc4]"><XCircle size={18} /></button></div>{children}</div></div>; }
